    def test_paired_components_8001B4A4(self):
        self.run_c('8001B4A4','\nVoiceState D_8004BEB8[4];static u32 lookup;static u16 expected_value;static int calls,mode,selected;static u8 seen[8];\nu32 func_8001EDF4(u32 key){assert(key==0x12345678U);return lookup;}\nvoid func_80020610(u8 command,u8 index,u8 channel,u8 value){assert(index<4);if((calls&1)==0){selected=(D_8004BEB8[index].flags24&2)!=0;assert(command==132&&value==(u8)(expected_value>>7));}else assert(command==133&&value==(expected_value&127));assert(channel==(selected?D_8004BEB8[index].channel55:D_8004BEB8[index].channel4B));seen[calls++]=index;if(calls&1){D_8004BEB8[index].flags24^=2;D_8004BEB8[index].channel55++;D_8004BEB8[index].channel4B++;}else if(index==0&&mode)D_8004BEB8[index].next10=mode==1?0xABCDEF02U:0xFFFFFFFFU;}\nint main(void){int mask,flags,i,j,m,expected_count,slot;u16 values[7]={0,1,127,128,32767,32768,65535};u8 expected_seen[8];for(mask=0;mask<16;mask++)for(flags=0;flags<16;flags++)for(j=0;j<7;j++)for(m=0;m<3;m++){memset(D_8004BEB8,0xA5,sizeof(D_8004BEB8));for(i=0;i<4;i++){D_8004BEB8[i].identifier60=0xABCDEF00U+i+((mask&(1<<i))?0:256);D_8004BEB8[i].next10=i==3?0xFFFFFFFFU:0xABCDEF01U+i;D_8004BEB8[i].flags24=flags&(1<<i)?2:0;D_8004BEB8[i].channel4B=13+i;D_8004BEB8[i].channel55=113+i;}lookup=0xABCDEF00U;expected_value=values[j];calls=0;mode=m;expected_count=0;slot=0;while(slot<4&&(mask&(1<<slot))){expected_seen[expected_count++]=(u8)slot;expected_seen[expected_count++]=(u8)slot;if(slot==0&&m)slot=m==1?2:4;else slot++;}assert(func_8001B4A4(0x12345678U,expected_value)==(expected_count?0:-1));assert(calls==expected_count&&memcmp(seen,expected_seen,(size_t)calls)==0);}lookup=0xFFFFFFFFU;calls=0;assert(func_8001B4A4(0x12345678U,0)==-1&&calls==0);return 0;}\n',False)
