    def test_keyed_pool_insertion(self):
        self.run_c('8001ECE0','\nSequenceNode *D_80050C50,*D_80050C54;static u32 counter;static int calls;\nu32 func_8001EAEC(void){u32 value;calls++;do{value=counter++;}while(value==0xFFFFFFFFU);return value;}\nint main(void){SequenceNode used[3],free_nodes[2],before[3];VoicePrefix state;int length,k,available,i,pos,expected_calls;u32 expected_key;SequenceNode *previous,*following;for(length=0;length<=3;length++)for(k=0;k<=8;k++)for(available=0;available<3;available++){memset(used,0,sizeof(used));memset(free_nodes,0,sizeof(free_nodes));memset(&state,0,sizeof(state));for(i=0;i<length;i++){used[i].key=1+i*2;used[i].value=0xFFFF0000U+i;used[i].previous=i?used+i-1:0;used[i].next=i+1<length?used+i+1:0;}free_nodes[0].next=available==2?free_nodes+1:0;free_nodes[1].previous=free_nodes;D_80050C50=length?used:0;D_80050C54=available?free_nodes:0;state.identifier60=0xABCDEF03U;state.entry18=0;memcpy(before,used,sizeof(used));counter=k;calls=0;expected_key=k;expected_calls=1;pos=0;while(pos<length&&expected_key>=used[pos].key){if(expected_key==used[pos].key){expected_key++;expected_calls++;}pos++;}previous=pos?used+pos-1:0;following=pos<length?used+pos:0;if(!available){assert(func_8001ECE0(&state)==0xFFFFFFFFU&&state.entry18==0&&memcmp(before,used,sizeof(used))==0);}else{assert(func_8001ECE0(&state)==expected_key&&state.entry18==free_nodes);assert(free_nodes[0].key==expected_key&&free_nodes[0].value==state.identifier60&&free_nodes[0].previous==previous&&free_nodes[0].next==following);assert(D_80050C50==(previous?used:free_nodes));if(previous)assert(previous->next==free_nodes);if(following)assert(following->previous==free_nodes);assert(D_80050C54==(available==2?free_nodes+1:0));if(available==2)assert(free_nodes[1].previous==0);for(i=0;i<length;i++)assert(used[i].key==before[i].key&&used[i].value==before[i].value);}assert(calls==expected_calls);}D_80050C50=0;D_80050C54=free_nodes;free_nodes[0].next=0;counter=0xFFFFFFFFU;calls=0;assert(func_8001ECE0(&state)==0&&counter==1&&calls==1);return 0;}\n',False)
    def test_sample_callback_live_ring_ranges(self):
        self.run_c('8001C3CC','\nSampleBuffer D_8004FA50[3];u8 D_8004FA18;static short storage[3][32];static u32 current[3];static int current_slot,calls,flushes,result,mutate,grow;static short *pointers[6];static u32 lengths[6];\nu32 func_80014C18(int i){current_slot=i;assert(i<3&&D_8004FA50[i].mode==1);return current[i];}\nstatic int callback(short *first,u32 first_count,short *second,u32 second_count,u32 context){SampleBuffer *r;r=D_8004FA50+current_slot;assert(first==r->buffer+r->position&&context==0x12345678U);if(current[current_slot]>r->position){assert(first_count==current[current_slot]-r->position&&second==0&&second_count==0);}else{assert(first_count==r->samples-r->position&&second==r->buffer&&second_count==current[current_slot]);}calls++;if(mutate){r->buffer=storage[current_slot]+8;r->position=0;r->samples=8;}if(grow&&current_slot==0){D_8004FA18=3;D_8004FA50[1].mode=0;D_8004FA50[2].mode=1;}return result;}\nvoid func_80014C40(short *p,u32 n){assert(flushes<6);pointers[flushes]=p;lengths[flushes++]=n;}\nint main(void){int old,now,ret,m,i;u32 expected_count;for(old=0;old<=8;old++)for(now=0;now<=8;now++)for(ret=0;ret<2;ret++)for(m=0;m<2;m++){memset(D_8004FA50,0,sizeof(D_8004FA50));D_8004FA18=1;D_8004FA50[0].mode=1;D_8004FA50[0].callback=callback;D_8004FA50[0].buffer=storage[0];D_8004FA50[0].samples=8;D_8004FA50[0].position=old;D_8004FA50[0].context=0x12345678U;current[0]=now;calls=flushes=0;result=ret;mutate=m;grow=0;func_8001C3CC();assert(calls==(old!=now)&&D_8004FA50[0].position==(u32)now);expected_count=old==now||!ret?0:(now>old?1:2);assert(flushes==(int)expected_count);if(flushes){assert(pointers[0]==storage[0]+(m?8:old));assert(lengths[0]==(u32)(now>old?(m?now:now-old):(m?8:8-old)));if(flushes==2)assert(pointers[1]==storage[0]+(m?8:0)&&lengths[1]==(u32)now);}}memset(D_8004FA50,0,sizeof(D_8004FA50));for(i=0;i<3;i++){D_8004FA50[i].mode=1;D_8004FA50[i].callback=callback;D_8004FA50[i].buffer=storage[i];D_8004FA50[i].samples=8;D_8004FA50[i].context=0x12345678U;current[i]=1;}D_8004FA18=1;grow=1;mutate=0;calls=flushes=0;result=1;func_8001C3CC();assert(calls==2&&flushes==2&&D_8004FA50[0].position==1&&D_8004FA50[1].position==0&&D_8004FA50[2].position==1);D_8004FA18=0;calls=0;func_8001C3CC();assert(calls==0);return 0;}\n',True)
